SELECT data['commit']['collection'] AS event, COUNT(*) AS cnt FROM bluesky GROUP BY event ORDER BY cnt DESC;
SELECT data['commit']['collection'] AS event, COUNT(*) AS cnt, COUNT(DISTINCT data['did']) AS users FROM bluesky WHERE data['kind'] = 'commit' AND data['commit']['operation'] = 'create' GROUP BY event ORDER BY cnt DESC;
SELECT data['commit']['collection'] AS event, EXTRACT(HOUR FROM (data['time_us'] / 1000)::TIMESTAMP WITH TIME ZONE) AS hour_of_day, COUNT(*) AS cnt FROM bluesky WHERE data['kind'] = 'commit' AND data['commit']['operation'] = 'create' AND data['commit']['collection'] IN ('app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like') GROUP BY event, hour_of_day ORDER BY hour_of_day, event;
SELECT data['did'] AS user_id, MIN((data['time_us'] / 1000)::TIMESTAMP WITH TIME ZONE) AS first_post_ts FROM bluesky WHERE data['kind'] = 'commit' AND data['commit']['operation'] = 'create' AND data['commit']['collection'] = 'app.bsky.feed.post' GROUP BY user_id ORDER BY first_post_ts ASC LIMIT 3;
SELECT data['did'] AS user_id, (MAX(data['time_us']) - MIN(data['time_us'])) / 1000 AS activity_span FROM bluesky WHERE data['kind'] = 'commit' AND data['commit']['operation'] = 'create' AND data['commit']['collection'] = 'app.bsky.feed.post' GROUP BY user_id ORDER BY activity_span DESC LIMIT 3;
